(50, 36, '旷课', '无故缺勤实践课4课时', '警告处分', '2025-12-25', 'ACTIVE');
INSERT INTO `midterm_assessment` (`id`, `student_id`, `semester`, `self_summary`, `advisor_comment`, `score`, `status`, `created_at`) VALUES
(1, 3, '2024-2025-1', '本学期认真学习各门课程，积极参加ACM竞赛培训，在编程能力上有显著提升。同时担任班长，组织班级活动多次，锻炼了组织协调能力。', '该生学习态度端正，成绩优秀，班干部工作认真负责。建议继续保持并加强基础理论学习。', 92.00, 'COMPLETED', '2024-12-20 10:00:00'),
(2, 4, '2024-2025-1', '本学习态度认真，专业课程均取得优异成绩，课余时间坚持编程训练，参加蓝桥杯获得好成绩。希望下学期继续保持。', '学习能力强，专业成绩突出，是班级的学习榜样。建议适当参加社团活动，全面发展。', 94.00, 'COMPLETED', '2024-12-20 10:00:00'),
(3, 5, '2024-2025-1', '本学期努力适应大学学习节奏，专业课学习较为认真，但在英语学习上还需要加强。积极参加志愿者活动，收获很大。', '该生学习努力，积极参加公益志愿活动，综合表现良好。建议加强英语和数学基础学习。', 82.00, 'COMPLETED', '2024-12-21 09:00:00'),
(4, 6, '2024-2025-1', '对本专业有浓厚兴趣，工程制图课程成绩较好。参加学院篮球队，增强了体质和团队意识。存在偶尔迟到的问题需要改正。', '该生专业兴趣浓厚，动手能力较强。需注意时间管理，改善迟到现象。', 78.00, 'COMPLETED', '2024-12-21 09:00:00'),
(5, 7, '2024-2025-1', '数学专业学习认真，成绩稳步提升。围棋水平有较大进步，参加市级比赛获得名次。希望能更多参与班级集体活动。', '学习认真踏实，数学基础扎实。性格偏内向，建议多参与团队协作活动。', 85.00, 'COMPLETED', '2024-12-22 10:00:00'),
(6, 8, '2024-2025-1', '英语学习兴趣浓厚，课外阅读大量英文原著。参加了演讲比赛获得经验。但其他通识课程投入时间不足，需要改善。', '英语专业能力突出，但需注意均衡发展各门课程。课外活动参与积极值得肯定。', 80.00, 'COMPLETED', '2024-12-22 10:00:00'),
(7, 9, '2024-2025-1', '计算机专业课程学习认真，编程能力提升明显。参加了人工智能社团，接触到很多前沿知识。希望下学期参与更多实践项目。', '专业学习目标明确，编程基础扎实。建议参加科研项目提升综合能力。', 88.00, 'COMPLETED', '2024-12-23 08:00:00'),
(8, 10, '2024-2025-1', '对电子信息专业兴趣浓厚，电路课程学习认真。家庭经济压力较大但心态积极，希望能获得勤工助学机会。', '该生学习努力，态度端正。家庭确有困难，建议申请助学岗位，同时保持学习成绩。', 76.00, 'COMPLETED', '2024-12-23 08:00:00'),
(9, 11, '2024-2025-1', '车辆工程专业学习渐入佳境，对汽车设计产生浓厚兴趣。课余时间阅读了大量汽车杂志和资料。团队协作能力较好。', '专业学习有兴趣，团队意识强。建议系统学习专业知识，打好理论基础。', 81.00, 'COMPLETED', '2024-12-24 09:00:00'),
(10, 12, '2024-2025-1', '信息与计算科学专业学习进度正常，对编程算法有浓厚兴趣。参加了ACM竞赛训练，提升了解题能力。课余时间喜欢下象棋。', '逻辑思维能力较强，专业学习主动。建议平衡理论学习与实践应用。', 86.00, 'COMPLETED', '2024-12-24 09:00:00'),
(11, 13, '2024-2025-1', '日语学习热情高，坚持每天背诵单词和练习听力。参加书法社团活动丰富，陶冶了情操。希望能有更多日语实践机会。', '语言学习刻苦认真，基础扎实。建议寻找语伴练习口语，提高应用能力。', 84.00, 'COMPLETED', '2024-12-25 08:00:00'),
(12, 14, '2024-2025-1', '对人工智能领域充满热情，课余时间系统学习了机器学习和Python。参加了相关竞赛并获奖，增强了学术科研信心。', '学习能力强，科研潜质突出。建议参与导师科研项目，夯实数学基础。', 90.00, 'COMPLETED', '2024-12-25 08:00:00'),
(13, 15, '2024-2025-1', '集成电路专业学习需要投入更多精力，本学习课程成绩中等。在实验室做了不少动手实践，对芯片设计有了更深理解。', '动手能力较好，但理论课程需要加强。建议制定详细学习计划，提高学习效率。', 74.00, 'COMPLETED', '2024-12-26 10:00:00'),
(14, 16, '2024-2025-1', '工业工程专业学习认真，对管理学和系统优化有浓厚兴趣。担任团支书，组织班级活动锻炼了领导能力。', '该生综合能力强，既重视学习又热心班级工作。继续保持全面发展。', 83.00, 'COMPLETED', '2024-12-26 10:00:00'),
(15, 17, '2024-2025-1', '统计学专业入门学习有一定难度，但坚持努力不放弃。参加了数据分析兴趣小组，对实际应用有了更多了解。', '学习态度认真，虽然基础较弱但进步明显。建议利用课余时间加强数学基础。', 75.00, 'COMPLETED', '2024-12-27 09:00:00'),
(16, 18, '2024-2025-1', '德语学习充满挑战但也很有收获，德语语法掌握较好。对德国文化产生浓厚兴趣，参加了中德文化交流活动。', '语言学习有天赋，学习态度积极。建议利用交换生项目机会提升语言水平。', 82.00, 'COMPLETED', '2024-12-27 09:00:00'),
(17, 19, '2024-2025-1', '网络工程专业学习进展顺利，对网络安全特别感兴趣。参加了CTF竞赛训练，技术能力提升迅速。', '专业方向明确，学习积极主动。网络安全方向有发展潜力，建议深入学习。', 87.00, 'COMPLETED', '2024-12-20 10:00:00'),
(18, 20, '2024-2025-1', '光电信息专业课程有一定难度，需要更加努力。对光学实验很感兴趣，动手能力较强。希望能够参与教师科研项目。', '实验动手能力好，理论学习需更加投入。建议多与专业课教师交流请教。', 73.00, 'COMPLETED', '2024-12-20 10:00:00'),
(19, 3, '2024-2025-2', '本学期继续保持良好学习状态，各科成绩保持在优秀水平。参加了全国数学建模竞赛，团队配合默契。ACM竞赛训练持续进行中。', '学习成绩持续优秀，竞赛表现突出。综合素质优秀，是同学们的榜样。继续保持。', 91.00, 'COMPLETED', '2025-06-20 10:00:00'),
(20, 4, '2024-2025-2', '本学习继续保持了学习热情，专业课程成绩优异。蓝桥杯国赛表现优秀，增强了自信。参与了老师的科研项目，收获良多。', '学习能力和科研能力突出，竞赛成绩优异。建议开始规划未来发展方向。', 93.00, 'COMPLETED', '2025-06-20 10:00:00'),
(21, 14, '2024-2025-2', '专业学习深入，在人工智能方向进展顺利。发表了第一篇学术论文，对科研有了更深的体会。算法能力持续提升中。', '科研潜质突出，论文发表是对学习成果的肯定。建议继续深入AI研究方向。', 91.00, 'COMPLETED', '2025-06-21 09:00:00'),
(22, 24, '2024-2025-2', '软件工程学习进展良好，Web开发和移动应用课程成绩优秀。参与了老师的开源项目，积累了实际开发经验。', '软件开发能力突出，实战经验丰富。建议注意理论课程与实践的平衡。', 89.00, 'COMPLETED', '2025-06-21 09:00:00'),
(23, 19, '2024-2025-2', '继续深入学习网络安全方向，CTF竞赛获得省级二等奖。课程学习保持稳定，算法和Web开发课程成绩较好。', '专业特长明显，竞赛表现突出。建议扩大知识面涉猎更多计算机方向。', 86.00, 'COMPLETED', '2025-06-22 08:00:00'),
(24, 5, '2024-2025-2', '本学期努力追赶学习进度，在学习上有了明显进步。志愿者活动持续参与，获得了校级表彰。感谢老师和同学的帮助。', '进步明显，学习态度值得肯定。志愿者工作表现优秀。保持积极向上的状态。', 80.00, 'COMPLETED', '2025-06-22 08:00:00'),
(25, 10, '2024-2025-2', '在学习上付出了更多努力，专业成绩有所提升。勤工助学工作认真负责，得到了老师的肯定。兼顾学习和工作虽然辛苦但很充实。', '该生虽然经济困难但自强不息，学习工作两不误。值得表扬，继续保持。', 78.00, 'COMPLETED', '2025-06-23 10:00:00'),
(26, 17, '2024-2025-2', '统计学学习渐入佳境，对数据分析产生了浓厚兴趣。参与了统计建模比赛，团队协作学到了很多。学习成绩稳步提升。', '进步明显，找到了适合自己的学习方向。建议多参与实际数据分析项目。', 79.00, 'COMPLETED', '2025-06-23 10:00:00'),
(27, 25, '2024-2025-2', '通信工程专业学习努力，专业课掌握较好。参加了物联网兴趣小组，拓宽了知识面。希望能有更多实验实践机会。', '学习态度认真，专业知识掌握扎实。建议多参与科技创新活动。', 81.00, 'COMPLETED', '2025-06-24 09:00:00'),
(28, 26, '2024-2025-2', '机械专业学习按部就班，动手实践能力有提升。机械制图和材料力学课程成绩良好。参加了金工实习获益良多。', '学习认真踏实，实践能力较好。建议增强创新意识，多参与设计竞赛。', 77.00, 'COMPLETED', '2025-06-24 09:00:00'),
(29, 27, '2024-2025-2', '信息与计算科学专业课程学习有一定挑战，算法相关课程掌握较好。程序设计能力持续提升中。准备参加暑期算法集训。', '编程算法能力突出，学习有明确目标。暑期集训计划很好，期待更大进步。', 84.00, 'COMPLETED', '2025-06-25 08:00:00'),
(30, 28, '2024-2025-2', '日语学习进展顺利，听说读写能力全面提升。参加了日语演讲比赛获得好评。对日本文化研究有了更深入的理解。', '语言学习进步显著，文化素养深厚。建议考虑日企实习或交换留学机会。', 85.00, 'COMPLETED', '2025-06-25 08:00:00'),
(31, 3, '2025-2026-1', '进入大三，专业方向更加明确。系统学习了算法、人工智能等课程，成绩保持优秀。继续积极参与科研和竞赛活动。', '该生综合素质优秀，已确定了明确的职业方向。建议开始准备研究生推免材料。', 92.00, 'COMPLETED', '2025-12-20 10:00:00'),
(32, 4, '2025-2026-1', '本学习深入学习算法和系统方向课程，成绩保持年级前列。积极参与导师科研项目，学术论文在投中。对未来规划更加清晰。', '学术潜质突出，科研能力持续提升。建议关注保研和出国深造机会。', 93.00, 'COMPLETED', '2025-12-20 10:00:00'),
(33, 14, '2025-2026-1', '人工智能方向深入学习，机器学习课程成绩优秀。参与了实验室的科研项目，接触到前沿研究。准备申请海外暑期科研实习。', '科研能力突出，发展方向明确。建议积极准备申请材料，争取海外交流机会。', 90.00, 'COMPLETED', '2025-12-21 09:00:00'),
(34, 24, '2025-2026-1', '专业课程学习保持优秀，软件设计和系统开发能力进一步提升。参与了学校信息中心项目开发，获得了实际工程经验。', '工程实践能力强，项目经验丰富。建议在系统架构方面深入学习。', 88.00, 'COMPLETED', '2025-12-21 09:00:00'),
(35, 29, '2025-2026-1', '大一第一学期，努力适应大学学习和生活节奏。计算机专业课程学习认真，对游戏开发方向产生兴趣。加入了编程社团。', '作为新生，适应能力较好，学习态度积极。建议打好编程和数学基础。', 83.00, 'COMPLETED', '2025-12-22 08:00:00'),
(36, 30, '2025-2026-1', '大一上学期，逐渐适应了大学学习方式。对电子信息技术有了初步了解，电路实验课表现出浓厚兴趣。', '适应大学生活顺利，专业兴趣正在培养中。建议多参加学术活动拓展视野。', 78.00, 'COMPLETED', '2025-12-22 08:00:00'),
(37, 31, '2025-2026-1', '大学第一学期，对车辆工程专业有了初步认识。喜欢动手实践课程，对3D打印技术特别感兴趣。加入了赛车社团。', '专业兴趣浓厚，动手能力强。建议平衡理论学习与实践操作。', 80.00, 'COMPLETED', '2025-12-23 10:00:00'),
(38, 32, '2025-2026-1', '大一第一学期适应期，统计学专业入门学习。对数据可视化产生兴趣，自学了相关工具。数学基础课程掌握较好。', '学习态度端正，有明确的学习目标。建议系统学习统计学基础理论。', 81.00, 'COMPLETED', '2025-12-23 10:00:00'),
(39, 33, '2025-2026-1', '法语学习充满热情，坚持每天听说练习。对法国文学和文化产生深厚兴趣。参加了法语角和击剑社团。', '语言学习积极性高，文化素养在提升。建议寻找更多法语实践交流机会。', 82.00, 'COMPLETED', '2025-12-24 09:00:00'),
(40, 34, '2025-2026-1', '人工智能专业入门学习，对NLP方向特别感兴趣。学习了Python编程和基本算法。加入了AI创新社团参与项目讨论。', '学习目标明确，专业兴趣浓厚。建议扎实学习数学和编程基础知识。', 84.00, 'COMPLETED', '2025-12-24 09:00:00'),
(41, 35, '2025-2026-1', '集成电路专业初步接触，对芯片设计产生了好奇心。电路基础课程学习认真，实验课动手操作收获很大。', '专业兴趣正在培养中，学习态度认真。建议多做课外阅读拓宽专业视野。', 77.00, 'COMPLETED', '2025-12-25 08:00:00'),
(42, 36, '2025-2026-1', '工业工程专业学习认真，对系统优化和管理科学有兴趣。参加了学院组织的企业参观活动，对实际应用有了了解。', '学习态度端正，专业方向逐渐明确。建议多参与实践项目和学科竞赛。', 79.00, 'COMPLETED', '2025-12-25 08:00:00'),
(43, 37, '2025-2026-1', '数学专业学习按部就班，对数学教育方向有兴趣。参加了志愿服务活动，帮助社区儿童辅导功课。', '该生有爱心和社会责任感，学习态度良好。建议明确职业规划方向。', 80.00, 'COMPLETED', '2025-12-26 10:00:00'),
(44, 38, '2025-2026-1', '英语专业学习积极主动，口语和听力进步显著。参加了英语戏剧社，表演能力得到锻炼。对国际商务方向有兴趣。', '语言学习进步快，综合素质发展均衡。建议修读商务英语相关课程。', 83.00, 'COMPLETED', '2025-12-26 10:00:00'),
(45, 6, '2025-2026-1', '机械专业课程学习有收获，液压与气动课程实践性强。在实验室做了多个项目，动手能力持续提升。对新能源方向开始关注。', '专业学习进步明显，实践能力较好。建议关注行业前沿技术发展。', 79.00, 'COMPLETED', '2025-12-27 09:00:00'),
(46, 9, '2025-2026-1', '计算机课程深入学习，对图形学和机器学习感兴趣。参加了多个竞赛并取得成绩。未来希望在游戏或AI方向发展。', '专业能力强，竞赛经验丰富。建议选择一个方向深入发展。', 87.00, 'COMPLETED', '2025-12-27 09:00:00'),
(47, 12, '2025-2026-1', '运筹学和最优化课程学习有难度但收获很大。数学建模能力进一步提升。参加了数学竞赛获得优异成绩。', '数学功底扎实，逻辑思维能力强。建议考虑运筹优化方向深入学习。', 86.00, 'COMPLETED', '2025-12-28 08:00:00'),
(48, 19, '2025-2026-1', '大三上学期，专业课程学习深入，云计算技术课程收获大。继续参加CTF竞赛训练，技术栈不断扩充。在考虑考研还是就业。', '专业能力扎实，竞赛经验丰富。建议尽早确定毕业方向并做好准备。', 85.00, 'COMPLETED', '2025-12-28 08:00:00'),
(49, 23, '2025-2026-1', '英语专业学习进入新阶段，学术写作能力有提升。参加了口译比赛获奖，增强了专业信心。在准备英语专业八级考试。', '专业能力突出，竞赛表现优秀。建议考虑翻译或教育方向深造。', 88.00, 'COMPLETED', '2025-12-29 09:00:00'),
(50, 27, '2025-2026-1', '运筹学和新课程学习投入较多精力，对数理逻辑和算法优化有了更深理解。暑期算法集训效果显著，编程能力大提升。', '算法能力突出，学习目标明确。建议考虑算法工程师方向。', 85.00, 'COMPLETED', '2025-12-29 09:00:00');
