(4, 6, 'CAMPUS_HAZARD', '教学楼走廊灯不亮', 'B区教学楼3楼走廊灯全部不亮，晚上行走非常危险', 'B区教学楼3楼', NULL, 'RESOLVED', 42, '2024-12-01 10:00:00', '2024-11-28 18:00:00'),
