INSERT INTO `private_message` (`id`, `sender_id`, `receiver_id`, `content`, `is_read`, `sent_at`) VALUES
(1, 3, 2, '张老师好，我想咨询一下关于奖学金申请的事情', 1, '2024-09-10 10:30:00'),
(2, 2, 3, '李同学你好，奖学金申请文件已经发到班级群了，请查看并按时提交', 1, '2024-09-10 10:35:00'),
(3, 4, 2, '老师，ACM竞赛的报名什么时候截止？', 1, '2024-09-15 14:00:00'),
(4, 2, 4, '王明辉同学，ACM报名截止日期是9月30日，请尽快组队', 1, '2024-09-15 14:10:00'),
(5, 5, 39, '李教授，您推荐的通信工程入门书籍是哪几本？', 1, '2024-09-20 09:00:00'),
(6, 39, 5, '推荐阅读《通信原理》和《信号与系统》，可以先从基础开始', 1, '2024-09-20 09:30:00'),
(7, 3, 4, '王明辉，周末一起去图书馆自习吗？', 1, '2024-10-11 18:00:00'),
(8, 4, 3, '好啊，周六早上9点图书馆门口见', 1, '2024-10-11 18:15:00'),
(9, 6, 41, '赵老师，工程制图作业的截止日期是下周几？', 0, '2024-10-20 10:00:00'),
(10, 9, 40, '吴教授，我对AI方向很感兴趣，有什么入门项目推荐吗？', 1, '2024-10-25 15:00:00'),
(11, 40, 9, '可以从手写数字识别开始，这个经典项目很适合入门', 1, '2024-10-25 15:30:00'),
(12, 14, 39, '老师，我想申请加入您的实验室，不知道还有名额吗？', 1, '2024-11-01 10:00:00'),
(13, 39, 14, '朱俊杰同学，现在还有一个本科生名额，欢迎下周来实验室面试', 1, '2024-11-01 11:00:00'),
(14, 3, 5, '刘思雨，志愿者活动报名链接发你一下', 1, '2024-11-10 12:00:00'),
(15, 5, 3, '收到了，谢谢班长！', 1, '2024-11-10 12:05:00'),
(16, 8, 42, '陈教授，英语演讲比赛的题目可以自己选吗？', 1, '2024-11-15 09:00:00'),
(17, 42, 8, '可以的，主题不限，时间控制在5-8分钟', 1, '2024-11-15 09:20:00'),
(18, 10, 45, '吕教授，电路实验报告可以晚一天交吗？', 1, '2024-12-01 16:00:00'),
(19, 45, 10, '可以的，但最迟明天下班前', 1, '2024-12-01 16:10:00'),
(20, 12, 3, '班长，数学建模比赛的队伍还能加人吗？', 0, '2024-12-10 20:00:00'),
(21, 19, 24, '韩晨光，你的开源项目我看了，代码写得真好', 1, '2025-01-05 14:00:00'),
(22, 24, 19, '谢谢！有兴趣的话欢迎来贡献PR', 1, '2025-01-05 14:15:00'),
(23, 7, 41, '王教授，关于概率论的课后习题我有几个问题', 1, '2025-02-15 10:00:00'),
(24, 41, 7, '明天下午3点我在办公室，你可以过来详细讨论', 1, '2025-02-15 10:30:00'),
(25, 13, 42, '陈老师，日语演讲的初稿写好了，想请您帮忙审阅', 0, '2025-03-01 08:00:00'),
(26, 17, 41, '王教授，统计建模的数据集从哪里下载？', 1, '2025-03-10 09:00:00'),
(27, 41, 17, '数据集已经上传到课程云盘了，请查看课程公告', 1, '2025-03-10 09:15:00'),
(28, 11, 6, '陈浩然，周末篮球约吗？', 1, '2025-03-20 17:00:00'),
(29, 6, 11, '当然！周六下午2点老地方', 1, '2025-03-20 17:10:00'),
(30, 16, 39, '老师，团日活动的策划方案请您过目', 1, '2025-04-05 10:00:00'),
(31, 39, 16, '方案很好，可以开始执行了', 1, '2025-04-05 10:30:00'),
(32, 18, 42, '陈教授，暑假有德国交换项目吗？', 1, '2025-04-15 11:00:00'),
(33, 42, 18, '有的，今年有慕尼黑工业大学的暑期项目，可以关注学院通知', 1, '2025-04-15 11:20:00'),
(34, 20, 15, '胡丽华，光电实验的数据你处理完了吗？', 0, '2025-05-01 14:00:00'),
(35, 22, 27, '袁思源，算法竞赛的组队邀请你收到了吗？', 1, '2025-05-10 16:00:00'),
(36, 27, 22, '收到了，我已经回复确认了', 1, '2025-05-10 16:10:00'),
(37, 23, 28, '邓佳琪，大艺展的舞蹈排练改成明天了', 0, '2025-05-20 20:00:00'),
(38, 25, 5, '刘思雨，通信原理的笔记可以借我看看吗？', 1, '2025-06-01 09:00:00'),
(39, 5, 25, '没问题，下午上课带给你', 1, '2025-06-01 09:15:00'),
(40, 26, 36, '蒋嘉诚，机械设计课设的图纸你画到哪了', 0, '2025-06-10 21:00:00'),
(41, 21, 16, '林睿阳，学生会纳新面试安排有变化', 0, '2025-09-10 10:00:00'),
(42, 28, 13, '马慧敏，日语话剧社招新想邀请你加入', 1, '2025-09-15 15:00:00'),
(43, 13, 28, '太好了！我一直想加入话剧社', 1, '2025-09-15 15:10:00'),
(44, 29, 34, '吕静怡，AI社团的迎新活动在哪里举办？', 1, '2025-10-01 10:00:00'),
(45, 34, 29, '在计算机学院报告厅，明天下午2点', 1, '2025-10-01 10:10:00'),
(46, 30, 35, '苏子涵，电子社团的元器件团购你参加吗', 1, '2025-10-15 11:00:00'),
(47, 35, 30, '参加的，帮我加一份', 1, '2025-10-15 11:05:00'),
(48, 31, 32, '曹雨桐，3D打印社的作品展你去参观吗', 0, '2025-11-01 14:00:00'),
(49, 33, 37, '蔡欣悦，法语社团的圣诞晚会你帮忙布置会场吗', 1, '2025-12-10 09:00:00'),
(50, 37, 33, '当然没问题，几点集合？', 1, '2025-12-10 09:10:00');
INSERT INTO `class_notice` (`id`, `class_identifier`, `title`, `content`, `publisher_id`, `is_pinned`, `published_at`) VALUES
(1, '软工2402班', '关于本学期奖学金评选工作的通知', '各位同学，本学期奖学金评选工作即将开始，请符合条件的同学准备好相关材料，于10月20日前提交至学院办公室。', 2, 1, '2024-10-01 08:00:00'),
(2, '通信2401班', '通信原理实验课时间调整通知', '由于实验室设备检修，本周四下午的通信原理实验课调整至周五上午进行，请相互转告。', 39, 0, '2024-10-10 09:00:00'),
(3, '机械2401班', '金工实习安排通知', '本学期金工实习将于11月1日至11月15日在工程训练中心进行，具体分组安排见附件，请提前做好准备。', 41, 1, '2024-10-15 10:00:00'),
(4, '数学2401班', '数学建模竞赛报名通知', '全国大学生数学建模竞赛校内选拔赛即将开始，有意参加的同学请于本周五前提交报名表。', 41, 0, '2024-10-20 08:00:00'),
(5, '英语2401班', '英语演讲比赛初赛通知', '外研社杯英语演讲比赛校级选拔赛将于下周三举行，欢迎各位同学积极报名。', 42, 0, '2024-10-25 09:00:00'),
(6, '计科2401班', '人工智能导论课程调课通知', '由于朱教授参加学术会议，下周一的AI导论课暂停一次，补课时间另行通知。', 40, 0, '2024-11-01 10:00:00'),
(7, '电信2401班', '电子设计大赛动员会通知', '本周五下午3点在电信学院报告厅召开电子设计大赛动员会，请全体同学参加。', 45, 0, '2024-11-05 08:00:00'),
(8, '车辆2401班', '比亚迪企业参观通知', '学院组织下周三参观比亚迪深圳总部，限定30人，先到先得，请速报名。', 41, 1, '2024-11-10 09:00:00'),
(9, '信计2401班', 'ACM编程竞赛培训通知', 'ACM竞赛周末培训班本周开始，每周六上午9:00-12:00在计算机实验室进行。', 40, 0, '2024-11-15 10:00:00'),
(10, '日语2401班', '日语演讲比赛决赛通知', '经过初赛选拔，最终进入决赛的10位同学请于下周五准备最终演讲，地点在外国语学院报告厅。', 42, 0, '2024-11-20 08:00:00'),
(11, '人工智能2401班', 'AI前沿讲座系列通知', '学院邀请了多位AI领域专家来做讲座，系列讲座从12月开始，每月一场，请关注具体时间。', 40, 1, '2024-11-25 09:00:00'),
(12, '集成2401班', '集成电路工艺实验安排', '本学期的IC工艺实验安排在12月1日至15日，请提前预习实验指导书。', 45, 0, '2024-11-30 10:00:00'),
(13, '工业2401班', '工业工程案例大赛通知', '学院将举办首届工业工程案例大赛，鼓励各位同学组队参加，获奖队伍有奖金和证书。', 41, 0, '2024-12-05 08:00:00'),
(14, '统计2401班', '统计软件培训通知', '为提升大家数据分析能力，下周二和周四晚将举办SPSS和R语言培训。', 41, 0, '2024-12-10 09:00:00'),
